function abilText(a, name){ if (!a) return ""; var fem=name && CAVE_H[name] && CAVE_H[name].fem, his=fem?"her":"his", p=function(v){ return Math.round(v*100)+"%"; }, W={self:fem?"herself":"himself",lane:his+" lane",team:"every ally",lowest:"the most hurt ally"}, o=[];
  if (a.leap) o.push("leaps next to "+(a.leap==="back"?"the enemy furthest back":"the most wounded enemy")+" and");
  var tg=a.leap?"it":"the target"; if (a.m) o.push("hits "+(a.all?"every enemy":a.lanes3?"every enemy in "+tg+"'s lane and the lanes either side":a.lane?"every enemy in "+tg+"'s lane":a.pierce?tg+" and everyone behind it":a.cnt?"the "+a.cnt+" nearest enemies":a.area?tg+" and every enemy next to it":tg)+" for "+p(a.m)+" damage");
  var x=[]; if (a.stun) x.push("stuns "+a.stun+"s"); if (a.bleed) x.push("bleeds "+p(a.bleed)+" of max health over 4s"); if (a.push) x.push("knocks back a tile"); if (a.exec) x.push("+"+p(a.exec)+" against enemies under 30% health"); if (a.ls) x.push("heals for "+p(a.ls)+" of the damage"); if (a.shred) x.push("strips "+p(a.shred)+" armour");
  if (x.length) o.push("("+x.join(", ")+")");
  if (a.weak) o.push((o.length?"; ":"")+(a.weakR>=99?"every enemy deals":a.weakR?"enemies near the target deal":"the target deals")+" "+p(a.weak)+" less damage for "+a.weakD+"s");
  if (a.strike) o.push((o.length?"; ":"")+"everyone in "+his+" lane strikes at once");
  if (a.heal) o.push((o.length?"; ":"")+"heals "+W[a.heal.w]+" "+p(a.heal.v)+" of max health");
  if (a.ward) o.push((o.length?"; ":"")+"shields "+W[a.ward.w]+" for "+p(a.ward.v)+" of max health");
  if (a.buff) o.push((o.length?"; ":"")+W[a.buff.w]+" gets "+[a.buff.atk?"+"+p(a.buff.atk)+" attack":"", a.buff.as?"+"+p(a.buff.as)+" attack speed":""].filter(Boolean).join(" and ")+" for "+a.buff.d+"s");
  if (a.dr) o.push((o.length?"; ":"")+(fem?"she":"he")+" takes "+p(a.dr.v)+" less damage for "+a.dr.d+"s");
  if (a.revive) o.push((o.length?"; ":"")+"once a fight, brings back the first fallen ally at "+p(a.revive));
  var s=o.join(" ").replace(/ and \(/," (").replace(/ ; /g,"; ").replace(/^./,function(c){ return c.toUpperCase(); }); return s+"."; }
