function castAbil(F, u, t){ var a=u.abil, opp=1-u.side, D=[], A=[]; u.charge=0; u.anim={k:"attack",t:F.t}; if (t) u.foe=t.id; u.casts=(u.casts||0)+1;
  if (a.leap && canWalk(u)){ var E=foes(F,u); if (E.length){ var tg=a.leap==="back"?E.sort(function(p,q){ return depthOf(q)-depthOf(p) || q.id-p.id; })[0]:E.sort(function(p,q){ return p.hp/p.max-q.hp/q.max || p.id-q.id; })[0];
      var best=null; for (var dx=-1;dx<=1;dx++) for (var dy=-1;dy<=1;dy++){ var g=tg.gx+dx, l=tg.lane+dy; if (g<0||g>2*ND-1||l<0||l>=NL||occ(F,g,l,u)) continue; var d=Math.abs(dx)+Math.abs(dy)+(g===tg.gx-fwd(u.side)?-.5:0); if (!best||d<best.d) best={g:g,l:l,d:d}; }
      if (best){ var fg=u.gx, fl=u.lane; u.gx=best.g; u.lane=best.l; u.lanes=[best.l]; u.move={t:.25, T:.25, fg:fg, fl:fl}; relane(F); t=tg; u.foe=tg.id; } } }
  if (a.m){ var hitL=function(l){ return laneOf(F,opp,l).filter(function(x){ return canHit(u,x); }); };
    if (a.all) D=foes(F,u);
    else if (a.lanes3) [t.lane-1,t.lane,t.lane+1].forEach(function(l){ if (l>=0 && l<NL) D=D.concat(hitL(l)); });
    else if (a.lane) D=hitL(t.lane);
    else if (a.pierce){ var L=laneOf(F,opp,t.lane), i=L.indexOf(t); D=(i<0?[t]:L.slice(i)).filter(function(x){ return canHit(u,x); }); }
    else if (a.cnt) D=foes(F,u).sort(nearer(u)).slice(0,a.cnt);
    else if (a.area) D=foes(F,u).filter(function(x){ return gap(t,x).d<=1; });
    else D=[t];
    D=D.filter(function(x, i){ return D.indexOf(x)===i; });
    D.forEach(function(x){ var mult=a.m; if (a.exec && x.hp<x.max*.3) mult*=1+a.exec; var d=dmgOf(F,u,x,{mult:mult}); var before=x.hp; hurt(F,u,x,d,{abil:1}); if (a.ls) heal(F,u,Math.max(0,before-Math.max(0,x.hp))*a.ls);
      if (!x.alive) return; var boss=x.kind==="boss";
      if (a.stun && !boss && !ccSafe(F,x)) x.stun=Math.max(x.stun,a.stun);
      if (a.bleed) x.dot={v:x.max*a.bleed/4, t:4};
      if (a.shred) x.shred=Math.min(.5,(x.shred||0)+a.shred);
      if (a.push && !boss && !x.big && !x.root && !knockSafe(F,x)){ var bk=x.gx-fwd(u.side); if (bk>=0 && bk<2*ND && !occ(F,bk,x.lane,x)){ x.gx=bk; relane(F); } } }); }
  if (a.weak){ var W=a.weakR>=99?foes(F,u):t?foes(F,u).filter(function(x){ return gap(t,x).d<=a.weakR; }):[]; W.forEach(function(x){ tmpBuf(x,"atk",-a.weak,a.weakD); }); D=D.concat(W.filter(function(x){ return D.indexOf(x)<0; })); }
  var mates=function(w){ var me=alive(F,u.side); return w==="self"?[u]:w==="lane"?me.filter(function(x){ return x.lane===u.lane; }):w==="lowest"?me.sort(function(p,q){ return p.hp/p.max-q.hp/q.max; }).slice(0,1):me; };
  if (a.revive && !F["rev"+u.side]){ var dead=F.units.filter(function(x){ return !x.alive && x.side===u.side && x.kind!=="boss" && x.gx!=null; }).sort(function(p,q){ return (p.diedAt||0)-(q.diedAt||0); })[0];
    if (dead){ F["rev"+u.side]=1; dead.alive=true; dead.hp=dead.max*a.revive; dead.gone=0; dead.anim={k:"idle",t:F.t}; insertUnit(F,dead,dead.lane,depthOf(dead)); ev(F,{k:"rise",u:dead.id}); A.push(dead); } }
  if (a.heal) mates(a.heal.w).forEach(function(x){ heal(F,x,x.max*a.heal.v); if (A.indexOf(x)<0) A.push(x); });
  if (a.ward) mates(a.ward.w).forEach(function(x){ x.ward=Math.max(x.ward||0, x.max*a.ward.v); if (A.indexOf(x)<0) A.push(x); });
  if (a.buff) mates(a.buff.w).forEach(function(x){ if (a.buff.atk) tmpBuf(x,"atk",a.buff.atk,a.buff.d); if (a.buff.as) tmpBuf(x,"as",a.buff.as,a.buff.d); if (A.indexOf(x)<0) A.push(x); });
  if (a.dr){ tmpBuf(u,"dr",a.dr.v,a.dr.d); }
  if (a.strike) alive(F,u.side).forEach(function(x){ if (x!==u && x.lane===u.lane) x.timer=Math.max(x.timer,1); });
  u.hits++; ev(F,{k:"abil", u:u.id, a:a.a, n:a.t, ts:D.map(function(x){ return x.id; }), al:A.map(function(x){ return x.id; }), l:t?t.lane:u.lane}); }

