function bossUnit(F, k, o){ var b=BOSS[k]||{}; o.side=1; o.kind=o.kind||"boss"; o.boss=o.boss||k; o.name=o.name||b.n; var u=mkUnit(F,o); u.weak=b.weak; u.air=o.air||0; u.only=o.only||0; u.beast=o.beast||0; u.fast=o.fast||0; u.allHitter=o.allHitter||0; u.art=o.art||b.art; u.scale=o.scale||1; return u; }
