function CS(){ var S=GS(); if (!S.cave) S.cave={run:null, best:0, tok:0, unl:{}, main:{}, runs:0, bosses:0}; var r=S.cave.run; if (r && r.board && r.board.length===3) to5x5(r); return S.cave; }
function to5x5(r){ var b=emptyBoard(); for (var l=0;l<3;l++) for (var s=0;s<3;s++) b[l+1][s]=r.board[l][s]||null; r.board=b;
  (r.banners||[]).forEach(function(x){ if (x.lane!=null) x.lane+=1; });
  if (r.next && r.next.line) r.next.line.forEach(function(e){ if (e.lane<3 && !e.moved){ e.lane+=1; e.moved=1; } }); }
