function interestOf(run){ var mul=1; boardFx(run,"interest").forEach(function(x){ mul=Math.max(mul,x.e.mul); }); return Math.min(interestCap(run), Math.floor(run.gold/10)*mul); } // +1 for every 10 gold kept (Cody, 23 Nov)
function heroPrice(run, name){ var p=HT_PRICE[tierOf(name)]; if (run.relics.indexOf("merc")>=0) p--; var d=CAVE_H[name]; if (name==="Francesco Sforza" && tiersOnName(run,name)>=2) p=0; if (name==="Abdalonymus" && tiersOnName(run,name)>=2) p=1; return Math.max(0,p); }
function tiersOnName(run, n){ var h=run.heroes.filter(function(x){ return x.name===n; })[0]; return h?tiersOn(h):0; }
function gearDiscount(run){ var d=0; boardFx(run,"gearDiscount").forEach(function(x){ d=Math.max(d,x.e.v); }); return d; }
