  if (e.k==="milvian"||e.k==="horn"||e.k==="cheat"||e.k==="guard") ui.nums.push({u:e.u, t:F.t, k:"s", s:{milvian:"Milvian Bridge!",horn:"Rally!",cheat:"Not yet!",guard:"Guarded"}[e.k]});
